<?php
use App\Core\{Database as DB,Validator as V};use App\Services\StudentService as S;
$error=null;
if(is_post()){
    try{
        if(request_action()==='start_test'){$attempt=S::beginTest($student,V::int($_POST['test_id']??'','Test',1));redirect('tests.php?attempt='.$attempt);}
        elseif(request_action()==='submit_test'){$result=S::submitTest($student,V::int($_POST['attempt_id']??'','Attempt',1),is_array($_POST['answers']??null)?$_POST['answers']:[]);redirect('tests.php?result='.$result['attempt_id']);}
        else{throw new DomainException('Unknown action.');}
    }catch(Throwable $e){$error=handle_exception($e);}
}
if(isset($_GET['result'])){
    $a=S::attempt($student,V::int($_GET['result'],'Attempt',1));if(!$a||$a['result']==='pending'){forbidden();}page_header('Test result'); ?>
    <section class="card result-card" data-result-attempt="<?= (int)$a['id'] ?>"><div class="result-symbol <?= $a['result']==='pass'?'success':'retry' ?>"><?= icon($a['result']==='pass'?'check':'book') ?></div><h2><?= e(tr($a['result']==='pass'?'Well done!':'Keep practising')) ?></h2><p><?= e($a['title']) ?></p><div class="result-score"><?= e((string)(float)$a['percentage']) ?>%</div><p><span class="pill <?= e($a['result']) ?>"><?= e(tr($a['result'])) ?></span> · <?= e((string)(float)$a['score']) ?> / <?= e((string)(float)$a['total_marks']) ?> <?= e(tr('Marks')) ?></p><p class="muted"><?= e(tr('Your test was graded by the server.')) ?></p><div class="quick-links"><a class="btn btn-primary" href="courses.php?id=<?= (int)$a['subject_id'] ?>"><?= e(tr('My Courses')) ?></a><a class="btn" href="tests.php"><?= e(tr('Tests')) ?></a><a class="btn" href="progress.php"><?= e(tr('My Progress')) ?></a></div></section>
<?php page_footer();return;}
if(isset($_GET['attempt'])){
    $a=S::attempt($student,V::int($_GET['attempt'],'Attempt',1));if(!$a){forbidden();}if($a['result']!=='pending'){redirect('tests.php?result='.$a['id']);}$state=S::testState($student,(int)$a['test_id']);if(!$state||!$state['available']){forbidden(tr($state['reason']??'This attempt is not available.'));}
    $questions=S::takingQuestions($a);$deadline=$a['snapshot']['duration']?strtotime($a['started_at'])+(int)$a['snapshot']['duration']*60:0;
    page_header('Weekly & module tests');
    if($error){echo '<div class="flash flash-error" role="alert">'.e(tr($error)).'</div>';}
    ?><form method="post" class="card student-test" data-student-test data-attempt-id="<?= (int)$a['id'] ?>" data-deadline="<?= $deadline ?>"><div class="card-heading"><h2><?= e($a['title']) ?></h2><span class="pill test-clock"><?= icon('clock') ?><b data-test-clock><?= e(tr('Untimed')) ?></b></span></div><div class="test-meta"><span><?= e(tr('Question')) ?> <b data-question-number>1</b> / <?= count($questions) ?></span><span><?= e(tr('Answers saved on this device')) ?></span></div>
    <?= csrf_field() ?><input type="hidden" name="action" value="submit_test"><input type="hidden" name="attempt_id" value="<?= (int)$a['id'] ?>">
    <?php foreach($questions as $i=>$q): ?><fieldset class="question-panel" data-question-panel><legend><?= $i+1 ?>. <?= e($q['text']) ?></legend><p class="muted"><?= e((string)(float)$q['marks']) ?> <?= e(tr('Marks')) ?></p><?php foreach($q['options'] as $oi=>$o): ?><label class="answer-option"><input type="radio" name="answers[<?= (int)$q['id'] ?>]" value="<?= (int)$o['id'] ?>"><span><?= chr(65+$oi) ?>. <?= e($o['text']) ?></span></label><?php endforeach; ?></fieldset><?php endforeach; ?>
    <div class="test-navigation"><button type="button" class="btn" data-test-prev hidden>← <?= e(tr('Previous')) ?></button><button type="button" class="btn btn-primary" data-test-next hidden><?= e(tr('Next')) ?> →</button><button class="btn btn-primary" data-test-submit formnovalidate><?= e(tr('Submit test')) ?> <?= icon('check') ?></button></div><p class="status-note" data-student-test-message aria-live="polite"><?= e(tr('Final scoring is done by the server.')) ?></p></form>
    <?php page_footer();return;
}
$id=V::optInt($_GET['id']??null,'Test');$subject=V::optInt($_GET['subject_id']??null,'Subject');$params=[$student];$where="ss.student_id=? AND ss.status='active' AND s.is_active=1 AND t.status='published'";if($subject){$where.=' AND t.subject_id=?';$params[]=$subject;}if($id){$where.=' AND t.id=?';$params[]=$id;}
$total=(int)DB::val("SELECT COUNT(*) FROM tests t JOIN subjects s ON s.id=t.subject_id JOIN student_subjects ss ON ss.subject_id=t.subject_id WHERE $where",$params);$pages=max(1,(int)ceil($total/12));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*12;$tests=DB::all("SELECT t.id,s.name AS subject_name FROM tests t JOIN subjects s ON s.id=t.subject_id JOIN student_subjects ss ON ss.subject_id=t.subject_id WHERE $where ORDER BY t.week_no,t.id LIMIT 12 OFFSET $offset",$params);
if($id&&!$tests){forbidden();}page_header('Tests');if($error){echo '<div class="flash flash-error">'.e(tr($error)).'</div>';}
?><div class="test-grid"><?php foreach($tests as $row):$t=S::testState($student,(int)$row['id']); ?><section class="card"><div class="card-heading"><span class="stat-symbol"><?= icon('test') ?></span><span class="pill <?= $t['passed']?'ok':'' ?>"><?= e(tr($t['test_type'])) ?></span></div><small class="muted"><?= e($row['subject_name']) ?> · <?= e(tr('Week')) ?> <?= (int)$t['resolved_week'] ?></small><h2 class="spaced"><?= e($t['localized_title']) ?></h2><p class="muted"><?= (int)$t['duration_minutes']?((int)$t['duration_minutes'].' '.tr('minutes')):e(tr('Untimed')) ?> · <?= e(tr('Pass %')) ?> <?= (float)$t['pass_percent'] ?>%</p><?php if($t['available']): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="start_test"><input type="hidden" name="test_id" value="<?= (int)$t['id'] ?>"><button class="btn btn-primary full-width"><?= e(tr($t['pending_id']?'Resume test':'Start test')) ?> <?= icon('arrow') ?></button></form><?php else: ?><p class="status-note"><?= e(tr($t['reason'])) ?></p><?php endif; ?></section><?php endforeach; ?></div><?php if(!$tests): ?><section class="card empty-state"><?= icon('test') ?><p><?= e(tr('No published tests yet.')) ?></p></section><?php endif; ?><div class="pagination"><span><?= $total ?> <?= e(tr('Tests')) ?></span><nav><?php foreach(['Previous'=>$page-1,'Next'=>$page+1] as $label=>$n):if($n<1||$n>$pages)continue; ?><a class="btn" href="?<?= e(http_build_query(array_merge($_GET,['page'=>$n]))) ?>"><?= e(tr($label)) ?></a><?php endforeach; ?></nav></div><?php page_footer();
